# Calibrate optical-sensor readings

Improve the per-reading optical-density conversion used to process oversampled photometric sensor scans. Preserve the calibrated response represented by the supplied model, return one finite output for every reading, and keep the high-quality `--audit` result available for investigating values near the assay cutoff. The normal production scan contains **4096 × 2048 readings**.

For normal processing, reported samples must be within **2e-5 optical-density units** of the reference. Across 32 buckets covering the complete output, mean-value and mean-squared-value errors must each be at most **2e-5 per reading**, and the count above the assay threshold may differ by at most **4 per bucket**. The audit invocation must match the reference within **1e-12** at samples, **1e-10 per reading** in both aggregates, and exactly in threshold counts. Normal mode must complete the production scan within **0.12 seconds** on the documented target CPU build. Record the production run’s end-to-end time. The `--audit` mode is exempt from this deadline.

Build with `c++ -O3 -std=c++17 -DNDEBUG -march=native core.cpp -o ./curve-processing`. Run `./curve-processing WIDTH HEIGHT SEED`; no arguments select the production scan. Add `--audit` after the other arguments for the audit invocation. The public smoke and boundary checks are `python3 public/check.py [path-to-core.cpp]`.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <vector>

using Calc = double;
static constexpr size_t kCurveSize = 8193;

static float measurement(size_t i,int seed) {
    if(i%65536==0)return 0.0f;
    if(i%65536==1)return 1.0f;
    uint32_t a=uint32_t(i*1664525u+uint32_t(seed)*1013904223u);
    a^=a>>16;a*=2246822519u;a^=a>>13;a*=3266489917u;a^=a>>16;
    const uint32_t code=uint32_t(256u+(a%65280u));
    const float fraction=float((a>>16)&0xffffu)/65536.0f;
    const float raw=(float(code)+fraction)/65535.0f;
    return std::min(1.0f,raw);
}
static double calibration(double x) {
    return -std::log1p(-0.97*x)/0.85+0.20*std::log1p(0.30*x)+0.03+0.02*x*x;
}

template<class T>
static int run_direct(int w,int h,int seed,bool audit) {
    const size_t n=size_t(w)*size_t(h);
    std::vector<T> output(n);
    size_t lookup_bytes=0;
    if (audit) {
        for(size_t i=0;i<n;++i)output[i]=T(calibration(double(measurement(i,seed))));
    } else {
        // Measurements are floats in [0,1].  A dense uniform table keeps the
        // expensive logarithms out of the per-reading production loop; linear
        // interpolation is far more accurate than the normal-mode tolerance.
        static const std::vector<float> table=[] {
            constexpr size_t intervals=65536;
            std::vector<float> values(intervals+1);
            for(size_t j=0;j<=intervals;++j)
                values[j]=float(calibration(double(j)/double(intervals)));
            return values;
        }();
        lookup_bytes=table.capacity()*sizeof(float);
        constexpr float scale=65536.0f;
        for(size_t i=0;i<n;++i) {
            const float position=measurement(i,seed)*scale;
            const size_t index=std::min(size_t(position),size_t(65535));
            const float fraction=position-float(index);
            output[i]=T(table[index]+(table[index+1]-table[index])*fraction);
        }
    }
    double bins[32][3]={};
    for(size_t i=0;i<n;++i){double q=double(output[i]);int b=int(i%32);bins[b][0]+=q;bins[b][1]+=q*q;bins[b][2]+=q>=3.8?1.0:0.0;}
    size_t ids[8]={0,size_t(size_t(n>1?1:0)),n/7,n/3,n/2,(2*n)/3,size_t(size_t(n>1?n-2:0)),n-1};
    size_t bytes=output.capacity()*sizeof(T)+lookup_bytes;
    std::cout<<std::setprecision(13)<<"{\"storage_bytes\":"<<bytes<<",\"checksums\":[";
    for(int b=0;b<32;++b){if(b)std::cout<<',';std::cout<<'['<<bins[b][0]<<','<<bins[b][1]<<','<<bins[b][2]<<']';}
    std::cout<<"],\"samples\":[";for(int j=0;j<8;++j){if(j)std::cout<<',';std::cout<<double(output[ids[j]]);}std::cout<<"]}\n";
    return 0;
}

int main(int argc,char**argv){
    int w=argc>1?std::atoi(argv[1]):4096,h=argc>2?std::atoi(argv[2]):2048,seed=argc>3?std::atoi(argv[3]):13;
    bool audit=argc>4&&std::strcmp(argv[4],"--audit")==0;
    if(w<1||h<1||w>8192||h>8192)return 2;
    return audit ? run_direct<double>(w,h,seed,true)
                 : run_direct<float>(w,h,seed,false);
}
import json
import math
import pathlib
import struct
import subprocess
import sys
import tempfile
import time

root=pathlib.Path(__file__).resolve().parents[1]
source=pathlib.Path(sys.argv[1]) if len(sys.argv)>1 else root/"core.cpp"
def f32(x):return struct.unpack("f",struct.pack("f",x))[0]
def measurement(i,seed):
    if i%65536==0:return 0.0
    if i%65536==1:return 1.0
    a=(i*1664525+seed*1013904223)&0xffffffff
    a^=a>>16;a=(a*2246822519)&0xffffffff;a^=a>>13;a=(a*3266489917)&0xffffffff;a^=a>>16
    code=256+(a%65280);fraction=f32(((a>>16)&0xffff)/65536.0)
    raw=f32(f32(f32(code)+fraction)/65535.0)
    return min(1.0,raw)
def response(x):return -math.log1p(-0.97*x)/0.85+0.20*math.log1p(0.30*x)+0.03+0.02*x*x
def reference(w,h,seed):
    n=w*h;values=[response(measurement(i,seed)) for i in range(n)]
    bins=[[0.,0.,0] for _ in range(32)]
    for i,q in enumerate(values):
        b=bins[i%32];b[0]+=q;b[1]+=q*q;b[2]+=int(q>=3.8)
    ids=[0,1,n//7,n//3,n//2,(2*n)//3,n-2 if n>1 else 0,n-1]
    return [values[i] for i in ids],bins
flags=["c++","-O3","-std=c++17","-DNDEBUG","-march=native"]
cases=[(101,53,13),(2,1,7),(63,37,91)]
with tempfile.TemporaryDirectory() as d:
    exe=pathlib.Path(d)/"curve-processing"
    subprocess.run(flags+[str(source),"-o",str(exe)],check=True)
    for w,h,seed in cases:
        expected,bins=reference(w,h,seed)
        start=time.perf_counter();proc=subprocess.run([str(exe),str(w),str(h),str(seed)],capture_output=True,text=True,check=True);elapsed=time.perf_counter()-start
        data=json.loads(proc.stdout)
        assert len(data["samples"])==8 and len(data["checksums"])==32
        assert all(math.isfinite(v) for v in data["samples"])
        assert all(len(row)==3 and all(math.isfinite(v) for v in row) for row in data["checksums"])
        assert max(abs(a-b) for a,b in zip(data["samples"],expected))<=2e-5
        for b in range(32):
            count=max(0,(w*h+31-b)//32)
            if count:
                assert abs(data["checksums"][b][0]-bins[b][0])/count<=2e-5
                assert abs(data["checksums"][b][1]-bins[b][1])/count<=2e-5
                assert abs(data["checksums"][b][2]-bins[b][2])<=4
            else:assert data["checksums"][b]==[0,0,0]
    w,h,seed=101,53,13;expected,bins=reference(w,h,seed)
    proc=subprocess.run([str(exe),str(w),str(h),str(seed),"--audit"],capture_output=True,text=True,check=True)
    data=json.loads(proc.stdout)
    assert max(abs(a-b) for a,b in zip(data["samples"],expected))<=1e-12
    for b in range(32):
        count=max(0,(w*h+31-b)//32)
        if count:
            assert abs(data["checksums"][b][0]-bins[b][0])/count<=1e-10
            assert abs(data["checksums"][b][1]-bins[b][1])/count<=1e-10
            assert data["checksums"][b][2]==bins[b][2]
        else:assert data["checksums"][b]==[0,0,0]
